    "listenings": [
      {
        "title": "Luyện nghe bài 6: Office Productivity Tools",
        "transcript": "Hello everyone! My name is Anna. I am 21 years old and I currently live in London. I am a university student studying languages. Today, I am very excited to share my experience with Office Productivity Tools. In my daily routine, I frequently use the word \"Spreadsheet\" when talking with friends. Yesterday afternoon, I spent one hour practicing \"Workflow\" with my classmates. In addition, knowing how to use \"Collaborate\" correctly helps me communicate much more naturally. I believe that practicing for fifteen minutes every day is the best secret to becoming confident. Thank you very much for listening!",
        "audioUrl": null,
        "questions": "[{\"question\":\"What is the speaker's name in the audio?\",\"options\":[\"Sarah\",\"Laura\",\"Emma\",\"Anna\"],\"correctAnswer\":\"Anna\",\"explanation\":\"The audio opens with the introduction: \\\"My name is Anna.\\\"\"},{\"question\":\"How old is the speaker and where does she live?\",\"options\":[\"20 years old, living in Edinburgh\",\"21 years old, living in London\",\"23 years old, living in Bristol\",\"22 years old, living in Manchester\"],\"correctAnswer\":\"21 years old, living in London\",\"explanation\":\"In the audio, the speaker says: \\\"I am 21 years old and I currently live in London.\\\"\"},{\"question\":\"What is the speaker's current occupation or role?\",\"options\":[\"University student studying languages\",\"Part-time language peer tutor\",\"Intern at an international cultural exchange center\",\"Graduate teaching assistant in linguistics\"],\"correctAnswer\":\"University student studying languages\",\"explanation\":\"The speaker clearly states: \\\"I am a university student studying languages.\\\"\"},{\"question\":\"Which vocabulary word did the speaker practice yesterday afternoon?\",\"options\":[\"Collaborate\",\"Workflow\",\"Task\",\"Spreadsheet\"],\"correctAnswer\":\"Workflow\",\"explanation\":\"The speaker mentions: \\\"Yesterday afternoon, I spent one hour practicing 'Workflow' with my classmates.\\\"\"},{\"question\":\"According to the speaker, what is the best secret to becoming confident?\",\"options\":[\"Memorizing fifty words without speaking practice\",\"Practicing for fifteen minutes every day\",\"Writing complex essays before practicing basic conversation\",\"Reviewing grammar rules once a month\"],\"correctAnswer\":\"Practicing for fifteen minutes every day\",\"explanation\":\"The speaker recommends: \\\"practicing for fifteen minutes every day is the best secret to becoming confident.\\\"\"}]"
      }
    ],
    "readings": [
      {
        "title": "Đọc hiểu bài 6: Office Productivity Tools",
        "passage": "Mastering the theme of \"Office Productivity Tools\" is a valuable step for every English learner at level B1.\n\nWhen exploring this topic, everyday words such as \"Spreadsheet\" and \"Workflow\" serve as the foundational building blocks. Language experts recommend that beginners should not merely memorize isolated definitions. Instead, connecting new vocabulary to real-life situations creates lasting memory pathways in the brain.\n\nFor example, when you understand how \"Collaborate\" functions within a complete sentence, you gain the confidence to express your thoughts clearly. Studies show that students who spend twenty minutes daily reading and repeating sentences aloud progress twice as fast as passive learners. Consistency, curiosity, and patience are the three essential keys to language mastery.",
        "translation": "Làm chủ chủ đề \"Office Productivity Tools\" là một bước tiến giá trị cho mọi người học tiếng Anh ở trình độ B1.\n\nKhi khám phá chủ đề này, những từ vựng quen thuộc như \"Spreadsheet\" (Bảng tính điện tử) và \"Workflow\" (Quy trình công việc) đóng vai trò là những viên gạch nền tảng. Các chuyên gia ngôn ngữ khuyên rằng người mới bắt đầu không nên chỉ học vẹt các định nghĩa rời rạc. Thay vào đó, việc liên kết từ mới với các tình huống đời thực sẽ tạo ra những đường dẫn ghi nhớ lâu dài trong não bộ.\n\nVí dụ, khi bạn hiểu cách từ \"Collaborate\" hoạt động trong một câu hoàn chỉnh, bạn sẽ có được sự tự tin để diễn đạt suy nghĩ một cách rõ ràng. Các nghiên cứu chỉ ra rằng những học viên dành hai mươi phút mỗi ngày để đọc và nhắc lại to các câu mẫu sẽ tiến bộ nhanh gấp đôi so với người học thụ động. Sự kiên trì, lòng tò mò và tính kiên nhẫn chính là ba chìa khóa thiết yếu để làm chủ ngôn ngữ.",
        "questions": "[{\"question\":\"What is the main topic of the reading passage?\",\"options\":[\"A comparative study on exam preparation strategies versus independent learning\",\"The psychological techniques for overcoming anxiety in public speaking\",\"The importance and effective methods of mastering Office Productivity Tools\",\"A historical overview of grammatical shifts in modern English communication\"],\"correctAnswer\":\"The importance and effective methods of mastering Office Productivity Tools\",\"explanation\":\"The passage primarily highlights the value and learning strategies for \\\"Office Productivity Tools\\\".\"},{\"question\":\"What do language experts recommend instead of memorizing isolated definitions?\",\"options\":[\"Translating full paragraphs word-for-word into mother tongue\",\"Reviewing vocabulary lists only once every two weeks\",\"Focusing exclusively on grammatical formulas without practicing sentences\",\"Connecting new vocabulary to real-life situations\"],\"correctAnswer\":\"Connecting new vocabulary to real-life situations\",\"explanation\":\"The passage recommends connecting new vocabulary to real-life situations to create lasting memory pathways.\"},{\"question\":\"According to the passage, how much daily reading practice helps learners progress twice as fast?\",\"options\":[\"Ten minutes before bedtime\",\"One hour every weekend\",\"Twenty minutes daily\",\"Forty-five minutes twice a week\"],\"correctAnswer\":\"Twenty minutes daily\",\"explanation\":\"The author notes that spending twenty minutes daily reading and repeating sentences aloud doubles learning progress.\"},{\"question\":\"In the passage, why is the word \\\"Spreadsheet\\\" highlighted?\",\"options\":[\"It serves as a foundational building block for the topic Office Productivity Tools\",\"It is primarily used as a formal greeting in business emails\",\"It represents an exceptional irregular verb form to memorize\",\"It is an advanced idiom reserved only for academic writing\"],\"correctAnswer\":\"It serves as a foundational building block for the topic Office Productivity Tools\",\"explanation\":\"The text points out that words like \\\"Spreadsheet\\\" serve as foundational building blocks.\"},{\"question\":\"What are the three essential keys to language mastery mentioned in the conclusion?\",\"options\":[\"Confidence, vocabulary breadth, and accent\",\"Speed, repetition, and memorization\",\"Fluency, grammar rules, and translation\",\"Consistency, curiosity, and patience\"],\"correctAnswer\":\"Consistency, curiosity, and patience\",\"explanation\":\"The passage concludes that consistency, curiosity, and patience are the three essential keys.\"}]"
      }
    ],
