    "readings": [
      {
        "title": "Đọc hiểu bài 10: The Passive Voice in Daily Life",
        "passage": "Mastering the theme of \"The Passive Voice in Daily Life\" is a valuable step for every English learner at level B1.\n\nWhen exploring this topic, everyday words such as \"Manufactured\" and \"Constructed\" serve as the foundational building blocks. Language experts recommend that beginners should not merely memorize isolated definitions. Instead, connecting new vocabulary to real-life situations creates lasting memory pathways in the brain.\n\nFor example, when you understand how \"Discovered\" functions within a complete sentence, you gain the confidence to express your thoughts clearly. Studies show that students who spend twenty minutes daily reading and repeating sentences aloud progress twice as fast as passive learners. Consistency, curiosity, and patience are the three essential keys to language mastery.",
        "translation": "Làm chủ chủ đề \"The Passive Voice in Daily Life\" là một bước tiến giá trị cho mọi người học tiếng Anh ở trình độ B1.\n\nKhi khám phá chủ đề này, những từ vựng quen thuộc như \"Manufactured\" (Được sản xuất) và \"Constructed\" (Được xây dựng) đóng vai trò là những viên gạch nền tảng. Các chuyên gia ngôn ngữ khuyên rằng người mới bắt đầu không nên chỉ học vẹt các định nghĩa rời rạc. Thay vào đó, việc liên kết từ mới với các tình huống đời thực sẽ tạo ra những đường dẫn ghi nhớ lâu dài trong não bộ.\n\nVí dụ, khi bạn hiểu cách từ \"Discovered\" hoạt động trong một câu hoàn chỉnh, bạn sẽ có được sự tự tin để diễn đạt suy nghĩ một cách rõ ràng. Các nghiên cứu chỉ ra rằng những học viên dành hai mươi phút mỗi ngày để đọc và nhắc lại to các câu mẫu sẽ tiến bộ nhanh gấp đôi so với người học thụ động. Sự kiên trì, lòng tò mò và tính kiên nhẫn chính là ba chìa khóa thiết yếu để làm chủ ngôn ngữ.",
        "questions": "[{\"question\":\"What is the main topic of the reading passage?\",\"options\":[\"A historical overview of grammatical shifts in modern English communication\",\"The psychological techniques for overcoming anxiety in public speaking\",\"A comparative study on exam preparation strategies versus independent learning\",\"The importance and effective methods of mastering The Passive Voice in Daily Life\"],\"correctAnswer\":\"The importance and effective methods of mastering The Passive Voice in Daily Life\",\"explanation\":\"The passage primarily highlights the value and learning strategies for \\\"The Passive Voice in Daily Life\\\".\"},{\"question\":\"What do language experts recommend instead of memorizing isolated definitions?\",\"options\":[\"Reviewing vocabulary lists only once every two weeks\",\"Translating full paragraphs word-for-word into mother tongue\",\"Connecting new vocabulary to real-life situations\",\"Focusing exclusively on grammatical formulas without practicing sentences\"],\"correctAnswer\":\"Connecting new vocabulary to real-life situations\",\"explanation\":\"The passage recommends connecting new vocabulary to real-life situations to create lasting memory pathways.\"},{\"question\":\"According to the passage, how much daily reading practice helps learners progress twice as fast?\",\"options\":[\"One hour every weekend\",\"Ten minutes before bedtime\",\"Forty-five minutes twice a week\",\"Twenty minutes daily\"],\"correctAnswer\":\"Twenty minutes daily\",\"explanation\":\"The author notes that spending twenty minutes daily reading and repeating sentences aloud doubles learning progress.\"},{\"question\":\"In the passage, why is the word \\\"Manufactured\\\" highlighted?\",\"options\":[\"It is primarily used as a formal greeting in business emails\",\"It represents an exceptional irregular verb form to memorize\",\"It is an advanced idiom reserved only for academic writing\",\"It serves as a foundational building block for the topic The Passive Voice in Daily Life\"],\"correctAnswer\":\"It serves as a foundational building block for the topic The Passive Voice in Daily Life\",\"explanation\":\"The text points out that words like \\\"Manufactured\\\" serve as foundational building blocks.\"},{\"question\":\"What are the three essential keys to language mastery mentioned in the conclusion?\",\"options\":[\"Fluency, grammar rules, and translation\",\"Speed, repetition, and memorization\",\"Consistency, curiosity, and patience\",\"Confidence, vocabulary breadth, and accent\"],\"correctAnswer\":\"Consistency, curiosity, and patience\",\"explanation\":\"The passage concludes that consistency, curiosity, and patience are the three essential keys.\"}]"
      }
    ],
