    "listenings": [
      {
        "title": "Luyện nghe bài 19: Phrasal Verbs in Daily Life (Part 1)",
        "transcript": "Hello everyone! My name is Anna. I am 21 years old and I currently live in London. I am a university student studying languages. Today, I am very excited to share my experience with Phrasal Verbs in Daily Life (Part 1). In my daily routine, I frequently use the word \"Look for\" when talking with friends. Yesterday afternoon, I spent one hour practicing \"Give up\" with my classmates. In addition, knowing how to use \"Turn down\" correctly helps me communicate much more naturally. I believe that practicing for fifteen minutes every day is the best secret to becoming confident. Thank you very much for listening!",
        "audioUrl": null,
        "questions": "[{\"question\":\"What is the speaker's name in the audio?\",\"options\":[\"Laura\",\"Sarah\",\"Anna\",\"Emma\"],\"correctAnswer\":\"Anna\",\"explanation\":\"The audio opens with the introduction: \\\"My name is Anna.\\\"\"},{\"question\":\"How old is the speaker and where does she live?\",\"options\":[\"20 years old, living in Edinburgh\",\"21 years old, living in London\",\"23 years old, living in Bristol\",\"22 years old, living in Manchester\"],\"correctAnswer\":\"21 years old, living in London\",\"explanation\":\"In the audio, the speaker says: \\\"I am 21 years old and I currently live in London.\\\"\"},{\"question\":\"What is the speaker's current occupation or role?\",\"options\":[\"Intern at an international cultural exchange center\",\"Graduate teaching assistant in linguistics\",\"Part-time language peer tutor\",\"University student studying languages\"],\"correctAnswer\":\"University student studying languages\",\"explanation\":\"The speaker clearly states: \\\"I am a university student studying languages.\\\"\"},{\"question\":\"Which vocabulary word did the speaker practice yesterday afternoon?\",\"options\":[\"Give up\",\"Find out\",\"Turn down\",\"Look for\"],\"correctAnswer\":\"Give up\",\"explanation\":\"The speaker mentions: \\\"Yesterday afternoon, I spent one hour practicing 'Give up' with my classmates.\\\"\"},{\"question\":\"According to the speaker, what is the best secret to becoming confident?\",\"options\":[\"Practicing for fifteen minutes every day\",\"Memorizing fifty words without speaking practice\",\"Writing complex essays before practicing basic conversation\",\"Reviewing grammar rules once a month\"],\"correctAnswer\":\"Practicing for fifteen minutes every day\",\"explanation\":\"The speaker recommends: \\\"practicing for fifteen minutes every day is the best secret to becoming confident.\\\"\"}]"
      }
    ],
    "readings": [
      {
        "title": "Đọc hiểu bài 19: Phrasal Verbs in Daily Life (Part 1)",
        "passage": "Mastering the theme of \"Phrasal Verbs in Daily Life (Part 1)\" is a valuable step for every English learner at level B1.\n\nWhen exploring this topic, everyday words such as \"Look for\" and \"Give up\" serve as the foundational building blocks. Language experts recommend that beginners should not merely memorize isolated definitions. Instead, connecting new vocabulary to real-life situations creates lasting memory pathways in the brain.\n\nFor example, when you understand how \"Turn down\" functions within a complete sentence, you gain the confidence to express your thoughts clearly. Studies show that students who spend twenty minutes daily reading and repeating sentences aloud progress twice as fast as passive learners. Consistency, curiosity, and patience are the three essential keys to language mastery.",
        "translation": "Làm chủ chủ đề \"Phrasal Verbs in Daily Life (Part 1)\" là một bước tiến giá trị cho mọi người học tiếng Anh ở trình độ B1.\n\nKhi khám phá chủ đề này, những từ vựng quen thuộc như \"Look for\" (Tìm kiếm vật gì) và \"Give up\" (Bỏ cuộc, từ bỏ) đóng vai trò là những viên gạch nền tảng. Các chuyên gia ngôn ngữ khuyên rằng người mới bắt đầu không nên chỉ học vẹt các định nghĩa rời rạc. Thay vào đó, việc liên kết từ mới với các tình huống đời thực sẽ tạo ra những đường dẫn ghi nhớ lâu dài trong não bộ.\n\nVí dụ, khi bạn hiểu cách từ \"Turn down\" hoạt động trong một câu hoàn chỉnh, bạn sẽ có được sự tự tin để diễn đạt suy nghĩ một cách rõ ràng. Các nghiên cứu chỉ ra rằng những học viên dành hai mươi phút mỗi ngày để đọc và nhắc lại to các câu mẫu sẽ tiến bộ nhanh gấp đôi so với người học thụ động. Sự kiên trì, lòng tò mò và tính kiên nhẫn chính là ba chìa khóa thiết yếu để làm chủ ngôn ngữ.",
        "questions": "[{\"question\":\"What is the main topic of the reading passage?\",\"options\":[\"A comparative study on exam preparation strategies versus independent learning\",\"The importance and effective methods of mastering Phrasal Verbs in Daily Life (Part 1)\",\"The psychological techniques for overcoming anxiety in public speaking\",\"A historical overview of grammatical shifts in modern English communication\"],\"correctAnswer\":\"The importance and effective methods of mastering Phrasal Verbs in Daily Life (Part 1)\",\"explanation\":\"The passage primarily highlights the value and learning strategies for \\\"Phrasal Verbs in Daily Life (Part 1)\\\".\"},{\"question\":\"What do language experts recommend instead of memorizing isolated definitions?\",\"options\":[\"Focusing exclusively on grammatical formulas without practicing sentences\",\"Translating full paragraphs word-for-word into mother tongue\",\"Connecting new vocabulary to real-life situations\",\"Reviewing vocabulary lists only once every two weeks\"],\"correctAnswer\":\"Connecting new vocabulary to real-life situations\",\"explanation\":\"The passage recommends connecting new vocabulary to real-life situations to create lasting memory pathways.\"},{\"question\":\"According to the passage, how much daily reading practice helps learners progress twice as fast?\",\"options\":[\"One hour every weekend\",\"Forty-five minutes twice a week\",\"Ten minutes before bedtime\",\"Twenty minutes daily\"],\"correctAnswer\":\"Twenty minutes daily\",\"explanation\":\"The author notes that spending twenty minutes daily reading and repeating sentences aloud doubles learning progress.\"},{\"question\":\"In the passage, why is the word \\\"Look for\\\" highlighted?\",\"options\":[\"It serves as a foundational building block for the topic Phrasal Verbs in Daily Life (Part 1)\",\"It is an advanced idiom reserved only for academic writing\",\"It is primarily used as a formal greeting in business emails\",\"It represents an exceptional irregular verb form to memorize\"],\"correctAnswer\":\"It serves as a foundational building block for the topic Phrasal Verbs in Daily Life (Part 1)\",\"explanation\":\"The text points out that words like \\\"Look for\\\" serve as foundational building blocks.\"},{\"question\":\"What are the three essential keys to language mastery mentioned in the conclusion?\",\"options\":[\"Fluency, grammar rules, and translation\",\"Speed, repetition, and memorization\",\"Consistency, curiosity, and patience\",\"Confidence, vocabulary breadth, and accent\"],\"correctAnswer\":\"Consistency, curiosity, and patience\",\"explanation\":\"The passage concludes that consistency, curiosity, and patience are the three essential keys.\"}]"
      }
    ],
